const items = $input.all();
const results = [];

for (const item of items) {
  const url = item.json['URL'] || '';
  let slug = url.replace(/\/$/, '').split('/').pop();

  let cidade = '';
  const matchCidade = slug.match(/em-(.+)$/);
  if (matchCidade) {
    cidade = matchCidade[1]
      .split('-')
      .map(p => p.charAt(0).toUpperCase() + p.slice(1))
      .join(' ');
  }

  results.push({
    json: {
      ...item.json,
      slug: slug,
      cidade: cidade,
      promocao: item.json['Promoção (%)'] || item.json['Promocao'] || item.json['PROMOÇÃO'] || '0',
      url_original: url,
      row_number: item.json['row_number'] || items.indexOf(item) + 2
    }
  });
}

return results;

